# -*- coding: utf-8 -*-
"""Check whether duplicated-anchor events cross split parts and share labels."""
import pandas as pd
import numpy as np

SRC = r"<PROJECT_ROOT>\05_rebuild_from_raw_20260511\03_baselines\R377_rolling02_next1s_vehicle_forecast_20260716\tables\R377_modeling_dataset.csv"
df = pd.read_csv(SRC)
H = [f"y_h{h}s_delta_from_issue" for h in
     ["0p1","0p2","0p3","0p4","0p5","0p6","0p7","0p8","0p9","1p0"]]

# use issue_offset==0 rows (one per event at anchor) if available
off_col = "issue_offset_s"
ev = df[df[off_col] == df.groupby("event_uid")[off_col].transform("min")].copy()
ev = ev.drop_duplicates("event_uid")

grpcols = ["recording", "anchor_abs_s"]
res = {"groups": 0, "cross_event_split": 0, "cross_rec_hash": 0, "cross_subj_hash": 0,
       "identical_y_pairs": 0, "pairs": 0}
for key, g in ev.groupby(grpcols):
    if len(g) < 2:
        continue
    res["groups"] += 1
    if g["split"].nunique() > 1:
        res["cross_event_split"] += 1
    if g["recording_hash_split"].nunique() > 1:
        res["cross_rec_hash"] += 1
    if g["subject_hash_split"].nunique() > 1:
        res["cross_subj_hash"] += 1
    ys = g[H].to_numpy()
    for i in range(len(ys)):
        for j in range(i + 1, len(ys)):
            res["pairs"] += 1
            if np.allclose(ys[i], ys[j], atol=1e-9):
                res["identical_y_pairs"] += 1
print(res)

# near-anchor (<2s) pairs crossing event_split, within same recording
cross_near = 0
total_near = 0
for rec, g in ev.groupby("recording"):
    g = g.sort_values("anchor_abs_s")
    a = g["anchor_abs_s"].to_numpy()
    s = g["split"].to_numpy()
    for i in range(len(g)):
        for j in range(i + 1, len(g)):
            d = a[j] - a[i]
            if d > 2.0:
                break
            total_near += 1
            if s[i] != s[j]:
                cross_near += 1
print("event pairs with anchor gap<=2s:", total_near, "crossing train/val/test:", cross_near)

# quantify feature identity for cross-split zero-gap pairs
feat_cols = [c for c in df.columns if c.startswith("issue_") and c not in ("issue_offset_s","issue_time_abs_s")]
n_ident_feat = 0
n_cross_pairs = 0
for key, g in ev.groupby(grpcols):
    if len(g) < 2 or g["split"].nunique() < 2:
        continue
    X = g[feat_cols].to_numpy(dtype=float)
    for i in range(len(X)):
        for j in range(i + 1, len(X)):
            if g["split"].iloc[i] != g["split"].iloc[j]:
                n_cross_pairs += 1
                if np.allclose(np.nan_to_num(X[i]), np.nan_to_num(X[j]), atol=1e-9):
                    n_ident_feat += 1
print("zero-gap cross-split pairs:", n_cross_pairs, "with identical 650-dim features:", n_ident_feat)

